package main

import (
	"errors"
	"fmt"
	"os"
	"runtime/pprof"

	"github.com/entireio/entire-brain/internal/cli"
)

var version = "dev-prof"

func main() {
	if p := os.Getenv("ENTIRE_BRAIN_CPUPROFILE"); p != "" {
		f, err := os.Create(p)
		if err == nil {
			pprof.StartCPUProfile(f)
			defer func() { pprof.StopCPUProfile(); f.Close() }()
		}
	}
	err := cli.Execute(version)
	if p := os.Getenv("ENTIRE_BRAIN_CPUPROFILE"); p != "" {
		pprof.StopCPUProfile()
	}
	if err != nil {
		if !errors.Is(err, cli.RenderedError()) {
			fmt.Fprintln(os.Stderr, err)
		}
		os.Exit(1)
	}
}
EOF
