	sort.SliceStable(occurrences, func(i, j int) bool {
		left, right := occurrences[i].CommittedAt, occurrences[j].CommittedAt
		if left == nil || right == nil {
			return left != nil && right == nil
		}
		return left.Before(*right)
	})
