	dir, _ := newBatchTestRepo(t, "x\n")
	for _, spec := range []string{"HEAD:a\nHEAD:b", "HEAD:has space.txt"} {
		if _, err := catFileBatchRead(context.Background(), dir, spec, true); err == nil {
