package cli

import (
	"context"
	"errors"
	"os"
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

func newBatchTestRepo(t *testing.T, content string) (dir, spec string) {
	t.Helper()
	dir = t.TempDir()
	run := func(args ...string) {
		t.Helper()
		cmd := exec.Command("git", args...)
		cmd.Dir = dir
		cmd.Env = append(os.Environ(),
			"GIT_AUTHOR_NAME=t", "GIT_AUTHOR_EMAIL=t@t",
			"GIT_COMMITTER_NAME=t", "GIT_COMMITTER_EMAIL=t@t",
			"GIT_CONFIG_GLOBAL=/dev/null", "GIT_CONFIG_SYSTEM=/dev/null")
		if out, err := cmd.CombinedOutput(); err != nil {
			t.Fatalf("git %v: %v\n%s", args, err, out)
		}
	}
	run("init", "-q", "-b", "main")
	if err := os.WriteFile(filepath.Join(dir, "blob.txt"), []byte(content), 0o600); err != nil {
		t.Fatal(err)
	}
	run("add", "blob.txt")
	run("commit", "-q", "-m", "one")
	return dir, "HEAD:blob.txt"
}

func TestCatFileBatchReadReturnsBlobContent(t *testing.T) {
	content := strings.Repeat("transcript line\n", 200)
	dir, spec := newBatchTestRepo(t, content)
	for range 3 { // repeated reads reuse one child and stay in sync
		got, err := catFileBatchRead(context.Background(), dir, spec, true)
		if err != nil {
			t.Fatal(err)
		}
		if string(got) != content {
			t.Fatalf("content mismatch: got %d bytes, want %d", len(got), len(content))
		}
	}
}

func TestCatFileBatchMissingIsDefinitiveAndNonFatal(t *testing.T) {
	dir, spec := newBatchTestRepo(t, "hello\n")
	_, err := catFileBatchRead(context.Background(), dir, "HEAD:absent.txt", true)
	if !errors.Is(err, errCatFileBatchMissing) {
		t.Fatalf("want errCatFileBatchMissing, got %v", err)
	}
	// The child must survive a missing answer and serve the next read.
	got, err := catFileBatchRead(context.Background(), dir, spec, true)
	if err != nil || string(got) != "hello\n" {
		t.Fatalf("read after missing: %q %v", got, err)
	}
}

func TestCatFileBatchRespawnsAfterChildDies(t *testing.T) {
	dir, spec := newBatchTestRepo(t, "respawn\n")
	ctx := context.Background()
	if _, err := catFileBatchRead(ctx, dir, spec, true); err != nil {
		t.Fatal(err)
	}
	key := catFileBatchKey{gitDir: dir, localOnly: true}
	catFileBatchMu.Lock()
	p := catFileBatchProcs[key]
	catFileBatchMu.Unlock()
	if p == nil {
		t.Fatal("expected a registered batch child")
	}
	p.fail()
	catFileBatchDrop(key, p)
	got, err := catFileBatchRead(ctx, dir, spec, true)
	if err != nil || string(got) != "respawn\n" {
		t.Fatalf("read after kill: %q %v", got, err)
	}
}

func TestLocalObjectTypeBatchAndFallbackAgree(t *testing.T) {
	dir, spec := newBatchTestRepo(t, "typed\n")
	ctx := context.Background()
	batched, err := localObjectType(ctx, ExecRunner{}, dir, spec)
	if err != nil {
		t.Fatal(err)
	}
	if batched != "blob" {
		t.Fatalf("want blob, got %q", batched)
	}
	if _, err := localObjectType(ctx, ExecRunner{}, dir, "HEAD:absent.txt"); !errors.Is(err, errCatFileBatchMissing) {
		t.Fatalf("want errCatFileBatchMissing, got %v", err)
	}
}

func TestCatFileWithPolicyMatchesPerExec(t *testing.T) {
	content := "policy parity\n"
	dir, _ := newBatchTestRepo(t, content)
	ctx := context.Background()
	for _, localOnly := range []bool{true, false} {
		got, err := catFileWithPolicy(ctx, ExecRunner{}, dir, "HEAD", "blob.txt", localOnly)
		if err != nil {
			t.Fatalf("localOnly=%v: %v", localOnly, err)
		}
		if string(got) != content {
			t.Fatalf("localOnly=%v: got %q", localOnly, got)
		}
	}
	if _, err := catFileWithPolicy(ctx, ExecRunner{}, dir, "HEAD", "absent.txt", true); err == nil {
		t.Fatal("want error for a missing path")
	}
}

func TestCatFileBatchRejectsNewlineSpec(t *testing.T) {
	dir, _ := newBatchTestRepo(t, "x\n")
	if _, err := catFileBatchRead(context.Background(), dir, "HEAD:a\nHEAD:b", true); err == nil {
		t.Fatal("want error for a spec containing a newline")
	}
}

