		mergedEnv = mergeCommandEnv(os.Environ(), env)
	}
	cmd := exec.CommandContext(ctx, name, args...)
	cmd.WaitDelay = commandWaitDelay
	if dir != "" {
		cmd.Dir = dir
	}
	if mergedEnv != nil {
		cmd.Env = mergedEnv
	}

